var o=document.getElementById("output"),n=document.getElementById("status");function s(e){o.textContent=typeof e=="string"?e:JSON.stringify(e,null,2)}async function r(e){n.textContent="Working\u2026";try{let t=await chrome.runtime.sendMessage(e);if(!t?.ok)throw new Error(t?.error||"Unknown error");return s(t.result),await c(),t.result}catch(t){return n.textContent="Error: "+t.message,s(t.message),null}}async function c(){let e=await chrome.runtime.sendMessage({type:"status"});if(e?.ok){let t=e.result;n.textContent=`${t.posts} posts \xB7 ${t.reports} reports \xB7 ${t.suggestions} suggestions \xB7 ${t.researchProvider}`}}document.getElementById("sync-feeds").addEventListener("click",()=>r({type:"syncFeeds"}));document.getElementById("sync-prices").addEventListener("click",()=>r({type:"syncPrices"}));document.getElementById("research").addEventListener("click",()=>{let e=document.getElementById("sku").value.trim();e&&r({type:"research",sku:e})});document.getElementById("clean").addEventListener("click",()=>{let e=document.getElementById("text").value;r({type:"cleanText",text:e})});document.getElementById("options").addEventListener("click",()=>chrome.runtime.openOptionsPage());c();document.getElementById("audit-tab").addEventListener("click",async()=>{n.textContent="Auditing this tab\u2026";try{let[e]=await chrome.tabs.query({active:!0,currentWindow:!0});if(!e)throw new Error("No active tab");let[{result:t}]=await chrome.scripting.executeScript({target:{tabId:e.id},func:()=>({url:location.href,title:document.title,description:document.querySelector('meta[name="description"]')?.content||"",canonical:document.querySelector('link[rel="canonical"]')?.href||"",h1:document.querySelector("h1")?.innerText||"",jsonLd:document.querySelectorAll('script[type="application/ld+json"]').length})});s(t),n.textContent="Tab audit complete"}catch(e){n.textContent="Audit failed: "+e.message,s(e.message)}});document.getElementById("analyze-ads").addEventListener("click",()=>{let e=document.getElementById("text").value;r({type:"analyzeAds",csv:e})});
